param([Parameter(Mandatory=$true)][string]$OutputRoot,[string]$DataRoot='C:\ProgramData\Capstone')
$ErrorActionPreference='Stop';New-Item -ItemType Directory -Force -Path $OutputRoot|Out-Null
foreach($kind in @('qms','erp')){$source=Join-Path $DataRoot "data\$kind";$target=Join-Path $OutputRoot $kind;if(!(Test-Path $source)){throw "Capstone $kind data is unavailable"};Copy-Item $source $target -Recurse -Force;if($kind -eq 'qms' -and (Test-Path "$DataRoot\data\qms_compatibility.json")){Copy-Item "$DataRoot\data\qms_compatibility.json" $target -Force};$files=Get-ChildItem $target -File -Recurse|Sort-Object FullName;$manifest=[ordered]@{format='capstone-business-data-v1';service=$kind;exported_utc=(Get-Date).ToUniversalTime().ToString('o');file_count=$files.Count;files=@()};foreach($file in $files){$manifest.files+=[ordered]@{path="$kind/$($file.FullName.Substring($target.Length+1).Replace('\','/'))";sha256=(Get-FileHash $file.FullName -Algorithm SHA256).Hash.ToLowerInvariant();size=$file.Length}};$manifest|ConvertTo-Json -Depth 5|Set-Content "$OutputRoot\$kind-data-manifest.json" -Encoding utf8}
[ordered]@{exported=$true;output_root=$OutputRoot;qms_manifest="$OutputRoot\qms-data-manifest.json";erp_manifest="$OutputRoot\erp-data-manifest.json"}|ConvertTo-Json
